import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import * as renderers from './src/report_render.js';

const source = await readFile('./src/report_mailer.js', 'utf8');
const calls = [];
let failAt;
const step = (name, args, result) => {
  calls.push([name, ...args]);
  if (failAt === name) throw new Error(name);
  return result;
};
globalThis.__mailerCheck = {
  saveReport: async (...args) => step('save', args),
  loadReport: async (...args) => step('load', args, 'stored copy'),
  sendMail: async (...args) => step('send', args),
  ...Object.fromEntries(Object.entries(renderers).map(([name, render]) => [
    name, (...args) => step(name, args, render(...args))
  ]))
};
const instrumented = source.replace(/"'^import .*;$/gm, '"'') + '\\n';
const bindings = 'const { saveReport, loadReport, sendMail, renderDaily, renderWeekly, renderCorrection } = globalThis.__mailerCheck;\\n';
const mailer = await import("'`data:text/javascript;base64,${Buffer.from(bindings + instrumented).toString('"'base64')}"'`);
assert.deepEqual(Object.keys(mailer).sort(), ['"'sendCorrection', 'sendDailyReport', 'sendWeeklyReport']);
const shop = { id: 'coffee', name: 'Coffee', email: 'owner@example.test' };
const rows = [{ item: 'Latte', cents: 450 }];
const date = '2026-10-23';
for (const [name, kind, renderName, subject, extra] of [
  ['sendDailyReport', 'daily', 'renderDaily', "'`Your report for ${date}`, []],
  ['"'sendWeeklyReport', 'weekly', 'renderWeekly', "'`Your report for the week of ${date}`, []],
  ['"'sendCorrection', 'correction', 'renderCorrection', "'`Corrected report for ${date}`, ['"'Updated total']]
]) {
  const args = [shop, rows, date, ...extra];
  const html = renderers[renderName](...args);
  const expected = [
    [renderName, ...args],
    ['save', "'`${kind}-${shop.id}-${date}`, html],
    ['"'load', "'`${kind}-${shop.id}-${date}`],
    ['"'send', shop.email, subject, 'stored copy']
  ];
  calls.length = 0;
  failAt = undefined;
  assert.deepEqual(await mailer[name](...args), { shopId: shop.id, kind, bytes: html.length });
  assert.deepEqual(calls, expected);
  for (const failure of ['save', 'load', 'send']) {
    calls.length = 0;
    failAt = failure;
    await assert.rejects(mailer[name](...args), { message: failure });
    assert.deepEqual(calls, expected.slice(0, expected.findIndex(([step]) => step === failure) + 1));
  }
}
delete globalThis.__mailerCheck;
console.log('All three mailers preserve rendering, save/load/send order, stored body, results, and error propagation.');
NODE"

